-- Create "approvals" table
CREATE TABLE "approvals" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "org_id" bigint NOT NULL, "tool_id" bigint NOT NULL, "tool_key" character varying NOT NULL, "tool_name" character varying NOT NULL, "risk_level" character varying NOT NULL DEFAULT 'high_risk', "requester_id" bigint NOT NULL, "conversation_id" bigint NULL, "message_id" bigint NULL, "tool_call_id" character varying NOT NULL DEFAULT '', "args" jsonb NULL, "args_hash" character varying NOT NULL DEFAULT '', "context_summary" character varying NOT NULL DEFAULT '', "approver_ids" jsonb NULL, "status" character varying NOT NULL DEFAULT 'pending', "decided_by" bigint NULL, "decision_comment" character varying NOT NULL DEFAULT '', "decided_at" timestamptz NULL, "expires_at" timestamptz NOT NULL, "exec_status" character varying NOT NULL DEFAULT 'none', "result" text NOT NULL DEFAULT '', "result_is_error" boolean NOT NULL DEFAULT false, "executed_at" timestamptz NULL, "trace_id" character varying NOT NULL DEFAULT '', PRIMARY KEY ("id"));
-- Create index "approval_conversation_id" to table: "approvals"
CREATE INDEX "approval_conversation_id" ON "approvals" ("conversation_id");
-- Create index "approval_org_id_status_expires_at" to table: "approvals"
CREATE INDEX "approval_org_id_status_expires_at" ON "approvals" ("org_id", "status", "expires_at");
-- Create index "approval_requester_id_created_at" to table: "approvals"
CREATE INDEX "approval_requester_id_created_at" ON "approvals" ("requester_id", "created_at");
